/* AZIZ DESIGN — builds the page from data.js (generated by build.py). */
(function () {
  "use strict";

  const DATA = window.AZIZ_DATA;
  const PAGE_SIZE = 8; // projects shown before "Show more projects"
  const PREVIEW = 3; // images shown per project; the last one turns into the "+N" tile
  const SEARCH_FROM = 7; // the search box appears once there are this many projects

  const UI = {
    en: {
      skip: "Skip to projects",
      "nav.work": "Work",
      "nav.about": "About",
      "nav.contact": "Contact",
      switchTo: "عربي",
      switchLabel: "التبديل إلى العربية",
      portfolio: "Portfolio",
      "stats.projects": "Projects",
      "stats.images": "Images",
      "stats.location": "Based in",
      "work.title": "Selected work",
      "work.note": "Tap any image to view it full screen.",
      "filter.label": "Filter projects by category",
      "filter.all": "All",
      "search.placeholder": "Search projects",
      "more.button": "Show more projects",
      "more.status": "Showing {shown} of {total} projects",
      noResults: "No projects match your search.",
      clear: "Clear filters",
      imagesCount: "{n} images",
      "plus.view": "View all",
      "plus.label": "Show all {n} images of {project}",
      showLess: "Show fewer images",
      imageAlt: "{project} — image {n} of {total}",
      "about.title": "About",
      "about.services": "Services",
      "contact.title": "Let’s work together",
      "contact.lead": "Have a project in mind? Get in touch.",
      "contact.email": "Email",
      "contact.phone": "Phone",
      "contact.whatsapp": "WhatsApp",
      "contact.facebook": "Facebook",
      "contact.instagram": "Instagram",
      "contact.linkedin": "LinkedIn",
      "contact.behance": "Behance",
      "contact.address": "Address",
      "footer.rights": "All rights reserved.",
      "footer.top": "Back to top",
      "lb.label": "Image viewer",
      "lb.close": "Close",
      "lb.prev": "Previous image",
      "lb.next": "Next image",
      empty: "No projects yet — add a folder of images inside projects/ and build the site again.",
      missing: "The site data was not found. Run “python3 build.py” and open _site/index.html.",
    },
    ar: {
      skip: "انتقل إلى المشاريع",
      "nav.work": "الأعمال",
      "nav.about": "نبذة",
      "nav.contact": "تواصل",
      switchTo: "EN",
      switchLabel: "Switch to English",
      portfolio: "معرض الأعمال",
      "stats.projects": "مشاريع",
      "stats.images": "صور",
      "stats.location": "المقر",
      "work.title": "أعمال مختارة",
      "work.note": "اضغط على أي صورة لعرضها بملء الشاشة.",
      "filter.label": "تصفية المشاريع حسب التصنيف",
      "filter.all": "الكل",
      "search.placeholder": "ابحث في المشاريع",
      "more.button": "عرض المزيد من المشاريع",
      "more.status": "يتم عرض {shown} من {total}",
      noResults: "لا توجد مشاريع مطابقة لبحثك.",
      clear: "مسح التصفية",
      imagesCount: "عدد الصور: {n}",
      "plus.view": "عرض الكل",
      "plus.label": "عرض كل صور {project} ({n})",
      showLess: "عرض صور أقل",
      imageAlt: "{project} — الصورة {n} من {total}",
      "about.title": "نبذة",
      "about.services": "الخدمات",
      "contact.title": "لنعمل معاً",
      "contact.lead": "لديك مشروع في ذهنك؟ تواصل معنا.",
      "contact.email": "البريد الإلكتروني",
      "contact.phone": "الهاتف",
      "contact.whatsapp": "واتساب",
      "contact.facebook": "فيسبوك",
      "contact.instagram": "إنستغرام",
      "contact.linkedin": "لينكدإن",
      "contact.behance": "بيهانس",
      "contact.address": "العنوان",
      "footer.rights": "جميع الحقوق محفوظة.",
      "footer.top": "العودة للأعلى",
      "lb.label": "عارض الصور",
      "lb.close": "إغلاق",
      "lb.prev": "الصورة السابقة",
      "lb.next": "الصورة التالية",
      empty: "لا توجد مشاريع بعد — أضف مجلداً من الصور داخل projects/ ثم أعد بناء الموقع.",
      missing: "لم يتم العثور على بيانات الموقع. شغّل “python3 build.py” ثم افتح _site/index.html.",
    },
  };

  const state = {
    lang: initialLang(),
    category: "all", // English name of the selected category, or "all"
    query: "",
    visible: PAGE_SIZE,
    expanded: new Set(), // projects whose "+N" tile was opened
    rendered: false,
  };
  const $ = (selector) => document.querySelector(selector);

  /* ---------- helpers ---------- */

  function initialLang() {
    const fromUrl = new URLSearchParams(location.search).get("lang");
    if (fromUrl === "en" || fromUrl === "ar") return fromUrl;
    try {
      const saved = localStorage.getItem("aziz-lang");
      if (saved === "en" || saved === "ar") return saved;
    } catch (e) { /* storage blocked: fall through */ }
    return (navigator.language || "").toLowerCase().startsWith("ar") ? "ar" : "en";
  }

  function t(key, vars) {
    let text = UI[state.lang][key] ?? UI.en[key] ?? key;
    if (vars) for (const [name, value] of Object.entries(vars)) text = text.replace(`{${name}}`, value);
    return text;
  }

  // Localized field from data.js: {"en": "...", "ar": "..."} (or a plain string).
  function loc(value) {
    if (!value) return "";
    if (typeof value === "string") return value;
    return value[state.lang] || value.en || value.ar || "";
  }

  const pad = (n) => String(n).padStart(2, "0");
  const isRTL = () => state.lang === "ar";
  const anchor = (project) => `project-${project.id}`;
  const ratio = (image) => (image.w && image.h ? image.w / image.h : 1.5);

  // Lower-case, and ignore Arabic diacritics / hamza forms so "اسكندرية" finds "الإسكندرية".
  function normalize(text) {
    return String(text)
      .toLowerCase()
      .normalize("NFKD")
      .replace(/[̀-ًͯ-ٰٟ]/g, "")
      .replace(/ة/g, "ه")
      .replace(/ى/g, "ي");
  }

  function h(tag, attrs, ...children) {
    const node = document.createElement(tag);
    for (const [key, value] of Object.entries(attrs || {})) {
      if (value == null || value === false) continue;
      if (key === "class") node.className = value;
      else if (key === "text") node.textContent = value;
      else if (key.startsWith("on")) node.addEventListener(key.slice(2), value);
      else node.setAttribute(key, value === true ? "" : value);
    }
    for (const child of children.flat()) if (child != null && child !== false && child !== "") node.append(child);
    return node;
  }

  // "Designing *form*" -> Designing <em>form</em>
  function withEmphasis(text) {
    return text.split("*").map((part, i) => (i % 2 ? h("em", { text: part }) : part));
  }

  function picture(image, alt, sizes) {
    const attrs = { src: image.thumb, alt, loading: "lazy", decoding: "async" };
    if (image.w && image.h) {
      attrs.width = image.w;
      attrs.height = image.h;
    }
    if (image.tw && image.src !== image.thumb) {
      attrs.srcset = `${image.thumb} ${image.tw}w, ${image.src} ${image.w}w`;
      attrs.sizes = sizes;
    }
    return h("img", attrs);
  }

  /* ---------- page ---------- */

  function render() {
    const root = document.documentElement;
    root.lang = state.lang;
    root.dir = isRTL() ? "rtl" : "ltr";

    document.querySelectorAll("[data-i18n]").forEach((node) => {
      node.textContent = t(node.dataset.i18n);
    });
    const toggle = $("#lang-toggle");
    toggle.textContent = t("switchTo");
    toggle.lang = isRTL() ? "en" : "ar";
    toggle.setAttribute("aria-label", t("switchLabel"));

    if (!DATA) {
      $("#projects").replaceChildren(h("p", { class: "notice", text: t("missing") }));
      return;
    }

    const { site } = DATA;
    const role = loc(site.role);
    document.title = role ? `${site.name} — ${role}` : site.name;

    renderHero(site);
    renderTools();
    renderProjects(!state.rendered);
    renderAbout(site);
    renderContact(site);
    $("#footer-copy").textContent = `© ${new Date().getFullYear()} ${site.copyright || site.name}. ${t("footer.rights")}`;
    setupLightboxLabels();
    state.rendered = true;
  }

  function renderHero(site) {
    const { projects } = DATA;
    const role = loc(site.role);
    $("#hero-eyebrow").textContent = role ? `${role} — ${t("portfolio")}` : t("portfolio");
    $("#hero-title").replaceChildren(...withEmphasis(loc(site.headline) || site.name));
    $("#hero-intro").textContent = loc(site.intro);

    const imageCount = projects.reduce((sum, p) => sum + p.images.length, 0);
    const stats = [
      ["stats.projects", pad(projects.length)],
      ["stats.images", pad(imageCount)],
      ["stats.location", loc(site.location)],
    ].filter(([, value]) => value);
    $("#hero-stats").replaceChildren(
      ...stats.map(([key, value]) => h("div", null, h("dt", { text: t(key) }), h("dd", { text: value })))
    );
    $("#work-note").textContent = t("work.note");
  }

  /* ---------- filters, search, paging ---------- */

  function categories() {
    const found = new Map();
    for (const project of DATA.projects) {
      if (!project.category) continue;
      const entry = found.get(project.category.en) || { label: project.category, count: 0 };
      entry.count += 1;
      found.set(project.category.en, entry);
    }
    return found;
  }

  function renderTools() {
    const cats = categories();
    const showFilters = cats.size > 1;
    const showSearch = DATA.projects.length >= SEARCH_FROM;
    if (!showFilters) state.category = "all";

    $("#work-tools").hidden = !showFilters && !showSearch;
    $("#search-box").hidden = !showSearch;
    const search = $("#search");
    search.placeholder = t("search.placeholder");
    search.setAttribute("aria-label", t("search.placeholder"));

    const filters = $("#filters");
    filters.hidden = !showFilters;
    filters.setAttribute("aria-label", t("filter.label"));
    if (!showFilters) return;
    const chip = (key, label, count) =>
      h(
        "button",
        { type: "button", class: "chip", "data-key": key, "aria-pressed": String(state.category === key), onclick: () => selectCategory(key) },
        label,
        h("span", { class: "chip-count", text: count })
      );
    filters.replaceChildren(
      chip("all", t("filter.all"), DATA.projects.length),
      ...[...cats].map(([key, entry]) => chip(key, loc(entry.label), entry.count))
    );
  }

  function selectCategory(key) {
    state.category = key;
    state.visible = PAGE_SIZE;
    $("#filters").querySelectorAll(".chip").forEach((chip) => {
      chip.setAttribute("aria-pressed", String(chip.dataset.key === key));
    });
    renderProjects(true);
  }

  function clearFilters() {
    state.category = "all";
    state.query = "";
    state.visible = PAGE_SIZE;
    $("#search").value = "";
    renderTools();
    renderProjects(true);
  }

  function filtered() {
    const words = normalize(state.query).split(/\s+/).filter(Boolean);
    return DATA.projects.filter((project) => {
      if (state.category !== "all" && (!project.category || project.category.en !== state.category)) return false;
      if (!words.length) return true;
      const text = normalize(
        [project.title, project.category, project.location]
          .flatMap((value) => (value ? [value.en, value.ar] : []))
          .concat(project.year || "")
          .join(" ")
      );
      return words.every((word) => text.includes(word));
    });
  }

  function renderProjects(animate) {
    const box = $("#projects");
    const list = filtered();
    const shown = list.slice(0, state.visible);

    if (!DATA.projects.length) {
      box.replaceChildren(h("p", { class: "notice", text: t("empty") }));
    } else if (!list.length) {
      box.replaceChildren(
        h("div", { class: "notice" }, h("p", { text: t("noResults") }), h("button", { type: "button", class: "pill", text: t("clear"), onclick: clearFilters }))
      );
    } else {
      box.replaceChildren(...shown.map(renderProject));
    }
    updateMore(list.length, shown.length);
    revealOnScroll(animate);
  }

  function updateMore(total, shown) {
    $("#more").hidden = shown >= total;
    $("#more-status").textContent = t("more.status", { shown, total });
    $("#more-button").textContent = t("more.button");
  }

  $("#more-button").addEventListener("click", () => {
    const list = filtered();
    const start = state.visible;
    state.visible += PAGE_SIZE;
    const added = list.slice(start, state.visible).map(renderProject);
    $("#projects").append(...added);
    updateMore(list.length, Math.min(state.visible, list.length));
    revealOnScroll(true);
    if (added.length) added[0].querySelector(".project-title").focus({ preventScroll: true });
  });

  $("#search").addEventListener("input", (event) => {
    state.query = event.target.value;
    state.visible = PAGE_SIZE;
    renderProjects(false);
  });

  /* ---------- one project ---------- */

  function renderProject(project) {
    const number = DATA.projects.indexOf(project) + 1;
    const title = loc(project.title);
    const images = project.images;
    const total = images.length;
    const expanded = state.expanded.has(project.id);
    const preview = images.slice(0, PREVIEW);
    const remaining = total - preview.length;
    const alt = (i) => t("imageAlt", { project: title, n: i + 1, total });

    const tiles = preview.map((image, i) => {
      const isPlus = i === preview.length - 1 && remaining > 0 && !expanded;
      const sizes = i === 0 && preview.length > 1 ? "(min-width: 900px) 45vw, 66vw" : "(min-width: 900px) 25vw, 50vw";
      if (isPlus) {
        return h(
          "button",
          {
            type: "button",
            class: "tile is-plus",
            "aria-expanded": "false",
            "aria-label": t("plus.label", { project: title, n: total }),
            onclick: () => toggleExpanded(project),
          },
          picture(image, "", sizes),
          h("span", { class: "plus", "aria-hidden": "true" }, h("strong", { dir: "ltr", text: `+${remaining}` }), h("span", { text: t("plus.view") }))
        );
      }
      return h("button", { type: "button", class: "tile", onclick: () => openLightbox(project, i) }, picture(image, alt(i), sizes));
    });

    const rest =
      expanded &&
      remaining > 0 &&
      h(
        "div",
        { class: "gallery" },
        images.slice(PREVIEW).map((image, j) => {
          const index = PREVIEW + j;
          return h(
            "button",
            { type: "button", class: "gallery-item reveal", style: `--r:${ratio(image).toFixed(4)}`, onclick: () => openLightbox(project, index) },
            picture(image, alt(index), "(min-width: 900px) 25vw, 50vw")
          );
        })
      );

    const meta = [loc(project.category), loc(project.location), project.year, t("imagesCount", { n: total })].filter(Boolean);
    const description = loc(project.description);

    return h(
      "article",
      { class: "project reveal", id: anchor(project), "aria-labelledby": `${anchor(project)}-title` },
      h(
        "header",
        { class: "project-info" },
        h(
          "div",
          { class: "project-sticky" },
          h("span", { class: "num", text: pad(number) }),
          h("h3", { class: "project-title", id: `${anchor(project)}-title`, tabindex: "-1", text: title }),
          h("p", { class: "project-meta", text: meta.join(" · ") }),
          description && h("p", { class: "project-desc", text: description })
        )
      ),
      h(
        "div",
        { class: "project-media" },
        h("div", { class: `mosaic mosaic-${preview.length}` }, tiles),
        rest,
        rest &&
          h("button", {
            type: "button",
            class: "pill show-less",
            "aria-expanded": "true",
            text: t("showLess"),
            onclick: () => toggleExpanded(project),
          })
      )
    );
  }

  function toggleExpanded(project) {
    const wasExpanded = state.expanded.has(project.id);
    if (wasExpanded) state.expanded.delete(project.id);
    else state.expanded.add(project.id);

    const fresh = renderProject(project);
    fresh.classList.add("is-in");
    document.getElementById(anchor(project)).replaceWith(fresh);
    revealOnScroll(true);

    if (wasExpanded) {
      fresh.scrollIntoView({ block: "start" });
      fresh.querySelector(".is-plus").focus({ preventScroll: true });
    } else {
      // The third image is now a normal tile; continue from the first newly shown image.
      fresh.querySelector(".gallery-item").focus({ preventScroll: true });
    }
  }

  /* ---------- about & contact ---------- */

  function renderAbout(site) {
    const about = loc(site.about);
    $("#about").hidden = !about && !site.services.length;
    $("#about-text").textContent = about;
    $("#services").replaceChildren(
      ...(site.services.length
        ? [
            h("h3", { class: "services-title", text: t("about.services") }),
            h(
              "ul",
              { class: "services" },
              site.services.map((service, i) =>
                h("li", null, h("span", { class: "num", text: pad(i + 1) }), h("span", { text: loc(service) }))
              )
            ),
          ]
        : [])
    );
  }

  function renderContact(site) {
    const c = site.contact || {};
    const web = (value, base) => (/^https?:\/\//i.test(value) ? value : base + value.replace(/^@/, ""));
    const rows = [
      ["email", c.email, (v) => `mailto:${v}`],
      ["phone", c.phone, (v) => `tel:${v.replace(/[^\d+]/g, "")}`],
      ["whatsapp", c.whatsapp, (v) => `https://wa.me/${v.replace(/\D/g, "")}`],
      ["facebook", c.facebook, (v) => web(v, "https://www.facebook.com/")],
      ["instagram", c.instagram, (v) => web(v, "https://instagram.com/")],
      ["linkedin", c.linkedin, (v) => web(v, "https://www.linkedin.com/in/")],
      ["behance", c.behance, (v) => web(v, "https://www.behance.net/")],
      ["address", c.address, (v) => `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(v)}`],
    ].filter(([, value]) => value);
    // A full link reads better as the studio's name than as a long URL.
    const shown = (value) => (/^https?:\/\//i.test(value) ? site.name : value);

    $("#contact").hidden = rows.length === 0;
    $("#contact-list").replaceChildren(
      ...rows.map(([key, value, link]) => {
        const external = !["email", "phone"].includes(key);
        return h(
          "li",
          null,
          h(
            "a",
            { href: link(value), target: external ? "_blank" : null, rel: external ? "noopener" : null },
            h("span", { class: "contact-label", text: t(`contact.${key}`) }),
            h("span", { class: "contact-value", dir: "ltr", text: shown(value) }),
            h("span", { class: "contact-arrow", "aria-hidden": "true", text: "↗" })
          )
        );
      })
    );
  }

  /* ---------- scroll effects ---------- */

  let observer = null;
  function revealOnScroll(animate) {
    const nodes = document.querySelectorAll(".reveal:not(.is-in)");
    if (!animate || !("IntersectionObserver" in window)) {
      nodes.forEach((node) => node.classList.add("is-in"));
      return;
    }
    if (observer) observer.disconnect();
    observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (!entry.isIntersecting) continue;
          entry.target.classList.add("is-in");
          observer.unobserve(entry.target);
        }
      },
      { rootMargin: "0px 0px -6% 0px" }
    );
    nodes.forEach((node) => observer.observe(node));
  }

  const header = $("#site-header");
  const onScroll = () => header.classList.toggle("is-scrolled", window.scrollY > 8);
  window.addEventListener("scroll", onScroll, { passive: true });
  onScroll();

  /* ---------- lightbox ---------- */

  const lb = {
    dialog: $("#lightbox"),
    img: $("#lb-img"),
    caption: $("#lb-caption"),
    count: $("#lb-count"),
    project: null,
    index: 0,
    token: 0,
  };

  function setupLightboxLabels() {
    lb.dialog.setAttribute("aria-label", t("lb.label"));
    $("#lb-close").setAttribute("aria-label", t("lb.close"));
    $("#lb-prev").setAttribute("aria-label", t("lb.prev"));
    $("#lb-next").setAttribute("aria-label", t("lb.next"));
    if (lb.dialog.open) showImage();
  }

  function openLightbox(project, index) {
    lb.project = project;
    lb.index = index;
    lb.dialog.classList.toggle("is-single", project.images.length < 2);
    showImage();
    if (!lb.dialog.open) {
      lb.dialog.showModal();
      document.documentElement.classList.add("is-locked");
    }
  }

  function showImage() {
    const { project, index } = lb;
    const images = project.images;
    const image = images[index];
    const total = images.length;
    const token = ++lb.token;

    // Show the (usually cached) thumbnail right away, then swap in the sharp version.
    lb.img.src = image.thumb;
    if (image.src !== image.thumb) {
      const full = new Image();
      full.onload = () => {
        if (token === lb.token) lb.img.src = image.src;
      };
      full.src = image.src;
    }
    lb.img.alt = t("imageAlt", { project: loc(project.title), n: index + 1, total });
    lb.caption.textContent = loc(project.title);
    lb.count.textContent = `${pad(index + 1)} / ${pad(total)}`;

    // Preload the neighbours so next / previous feel instant.
    for (const step of [1, -1]) new Image().src = images[(index + step + total) % total].src;
  }

  function step(direction) {
    const total = lb.project.images.length;
    lb.index = (lb.index + direction + total) % total;
    showImage();
  }

  $("#lb-close").addEventListener("click", () => lb.dialog.close());
  $("#lb-prev").addEventListener("click", () => step(-1));
  $("#lb-next").addEventListener("click", () => step(1));

  lb.dialog.addEventListener("close", () => {
    document.documentElement.classList.remove("is-locked");
    lb.token++;
    lb.img.removeAttribute("src");
  });

  lb.dialog.addEventListener("keydown", (event) => {
    if (event.key !== "ArrowRight" && event.key !== "ArrowLeft") return;
    event.preventDefault();
    // In Arabic (right-to-left) the "next" image is to the left.
    step((event.key === "ArrowRight") !== isRTL() ? 1 : -1);
  });

  // Click on the empty area around the image closes the viewer.
  $("#lb-stage").addEventListener("click", (event) => {
    if (event.target.id === "lb-stage") lb.dialog.close();
  });

  // Swipe on phones.
  let touchX = null;
  lb.dialog.addEventListener("touchstart", (event) => { touchX = event.touches[0].clientX; }, { passive: true });
  lb.dialog.addEventListener("touchend", (event) => {
    if (touchX == null) return;
    const dx = event.changedTouches[0].clientX - touchX;
    touchX = null;
    if (Math.abs(dx) < 40) return;
    const swipedLeft = dx < 0;
    step(swipedLeft !== isRTL() ? 1 : -1);
  });

  /* ---------- language ---------- */

  $("#lang-toggle").addEventListener("click", () => {
    state.lang = isRTL() ? "en" : "ar";
    try {
      localStorage.setItem("aziz-lang", state.lang);
    } catch (e) { /* storage blocked: the choice lasts until the page is closed */ }
    render();
  });

  render();

  // Sections are created by this script, so jump to a shared link (#project-…, #contact…) once they exist.
  if (DATA && location.hash) {
    const id = decodeURIComponent(location.hash.slice(1));
    const project = DATA.projects.find((p) => anchor(p) === id);
    if (project) {
      if (!filtered().includes(project)) clearFilters();
      const position = filtered().indexOf(project);
      if (position >= state.visible) {
        state.visible = Math.ceil((position + 1) / PAGE_SIZE) * PAGE_SIZE;
        renderProjects(false);
      }
    }
    const target = document.getElementById(id);
    if (target) target.scrollIntoView();
  }
})();
